from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class PlanActivationV1(SchemaObject):
    link = SchemaField(name="link")
    resp = SchemaField(name="resp", not_null=True)

    def __init__(self, link, resp):
        self.link = link
        self.resp = resp

        super(PlanActivationV1, self).__init__()
